'use client';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { ArrowUpRight, ArrowDownLeft, ArrowRight, Plus, LayoutDashboard, ArrowLeftRight, Wallet, Banknote, PieChart, TrendingUp, CalendarDays, Target, Sparkles, Upload, Settings, ChevronDown, Search, Moon, Sun, LogOut, Menu, X, CreditCard, Building2, ChevronLeft, ChevronRight, MoreHorizontal, Check, Mic, Send, Download, ShieldCheck, Info, Trash2, Pencil, Undo2 } from 'lucide-react';
import { api, ApiError, money, toPaise, localDate } from '@/lib/api';
import type { User, Dashboard, Transaction, Page, Category, Account, Budget, Goal, Bill, ImportJob } from '@/lib/types';
import { Empty, ErrorState, Loading, Modal, Progress, Trend } from './ui';

const navigation = [
  {id:'overview',label:'Overview',icon:LayoutDashboard}, {id:'transactions',label:'Transactions',icon:ArrowLeftRight}, {id:'accounts',label:'Accounts',icon:Wallet}, {id:'cash',label:'Cash wallet',icon:Banknote},
  {id:'budgets',label:'Budgets',icon:PieChart}, {id:'insights',label:'Insights',icon:TrendingUp}, {id:'recurring',label:'Bills & subscriptions',icon:CalendarDays}, {id:'goals',label:'Savings goals',icon:Target},
  {id:'assistant',label:'Mint Copilot',icon:Sparkles}, {id:'import',label:'Import transactions',icon:Upload},
];
type Dialog = {type:string; transaction?:Transaction; goal?:Goal};
type DialogProps = {dialog:Dialog; accounts:Account[]; categories:Category[]; dashboard:Dashboard; close:()=>void; done:()=>void};

export default function Workspace({section}: {section:string}) {
  const router=useRouter(), cache=useQueryClient();
  const [dialog,setDialog]=useState<Dialog|null>(null), [mobileMenu,setMobileMenu]=useState(false), [light,setLight]=useState(false), [notice,setNotice]=useState('');
  const [range,setRange]=useState('cycle'),[start,setStart]=useState(localDate().slice(0,7)+'-01'),[end,setEnd]=useState(localDate());
  const user=useQuery({queryKey:['me'],queryFn:()=>api<User>('auth/me'),retry:false});
  const dateQuery=range==='custom'?`?start=${start}&end=${end}`:range==='month'?`?start=${localDate().slice(0,7)}-01&end=${localDate()}`:'';
  const dashboard=useQuery({queryKey:['dashboard',dateQuery],queryFn:()=>api<Dashboard>('dashboard'+dateQuery),enabled:!!user.data});
  const categories=useQuery({queryKey:['categories'],queryFn:()=>api<Category[]>('categories'),enabled:!!user.data});
  const recent=useQuery({queryKey:['recent'],queryFn:()=>api<Page<Transaction>>('transactions?page_size=5'),enabled:!!user.data&&section==='overview'});
  useEffect(()=>{if(user.error instanceof ApiError&&user.error.status===401)router.replace('/login');},[user.error,router]);
  useEffect(()=>{setLight(localStorage.getItem('ps_theme')==='light');},[]);
  useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(id);}},[notice]);
  const done=()=>{setDialog(null);void cache.invalidateQueries();setNotice('All set. Your finances are up to date.');};
  const logout=async()=>{try{await api('auth/logout',{method:'POST'});cache.clear();router.replace('/login');}catch(e){setNotice((e as Error).message);}};
  if(user.isPending) return <div className="full-loading"><span className="brand-mark"><ArrowUpRight/></span><p>Making sense of your money…</p></div>;
  if(user.error) return <div className="standalone"><ErrorState message={user.error.message} retry={()=>void user.refetch()}/><Link href="/login" className="text-link">Back to sign in</Link></div>;
  const data=dashboard.data;
  const current=navigation.find(n=>n.id===section);
  return <div className={`app-shell ${light?'light':''}`}>
    <aside className={`sidebar ${mobileMenu?'is-open':''}`}><Link href="/" className="brand"><span className="brand-mark"><ArrowUpRight size={24}/></span><span>morrow<b>mint</b></span></Link><button className="mobile-close icon-button" onClick={()=>setMobileMenu(false)} aria-label="Close menu"><X/></button><div className="workspace-label"><span className="workspace-dot"/> Personal workspace<ChevronDown size={13}/></div><div className="nav-group-label">YOUR MONEY</div><nav aria-label="Main navigation">{navigation.map((nav,i)=><div key={nav.id}>{i===8&&<div className="nav-group-label tools-label">A LITTLE EXTRA CLARITY</div>}<Link onClick={()=>setMobileMenu(false)} href={nav.id==='overview'?'/':`/${nav.id}`} className={`nav-item ${section===nav.id?'active':''}`} aria-current={section===nav.id?'page':undefined}><nav.icon size={18}/><span>{nav.label}</span>{nav.id==='assistant'&&<span className="ai-tag">AI</span>}{section===nav.id&&<span className="active-dot"/>}</Link></div>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><div className="little-spark"><Sparkles size={18}/></div><strong>A little more intentional.</strong><p>Small money habits.<br/>More space for your dreams.</p><Link href="/goals">Set your next goal <ArrowUpRight size={14}/></Link></div><Link href="/settings" className={`nav-item ${section==='settings'?'active':''}`}><Settings size={18}/>Settings</Link><div className="profile"><span className="avatar">{user.data?.name.slice(0,1).toUpperCase()}</span><div><strong>{user.data?.name}</strong><span>Personal account</span></div><button className="icon-button" onClick={logout} aria-label="Sign out"><LogOut size={17}/></button></div></div></aside>
    {mobileMenu&&<button aria-label="Close menu" className="sidebar-overlay" onClick={()=>setMobileMenu(false)}/>}
    <div className="main-wrapper"><header className="topbar"><div className="breadcrumb"><button className="mobile-menu icon-button" aria-label="Open menu" onClick={()=>setMobileMenu(true)}><Menu/></button><span>My workspace</span><ChevronRight size={13}/><strong>{current?.label||'Settings'}</strong></div><div className="topbar-actions"><span className="private-label"><ShieldCheck size={14}/> Your space. Your money.</span><button className="icon-button" aria-label={light?'Switch to dark theme':'Switch to light theme'} onClick={()=>{setLight(!light);localStorage.setItem('ps_theme',!light?'light':'dark');}}>{light?<Moon size={18}/>:<Sun size={18}/>}</button><span className="avatar avatar-small">{user.data?.name.slice(0,1).toUpperCase()}</span></div></header>
      <main className="main-content"><motion.div key={section} initial={{opacity:0,y:6}} animate={{opacity:1,y:0}} transition={{duration:.2}}><div className="page-heading"><div><div className="eyebrow">{section==='overview'?new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date()).toUpperCase():'A CLEARER PICTURE OF YOUR MONEY'}</div><h1>{section==='overview'?<>Hello, {user.data?.name.split(' ')[0]}<span className="heading-dot">.</span></>:current?.label||'Your preferences'}</h1><p>{section==='overview'?"Here’s your money at a glance. Let’s make it count.":sectionDescriptions[section]}</p></div><div className="heading-actions">{['overview','insights'].includes(section)&&<select aria-label="Dashboard period" value={range} onChange={e=>setRange(e.target.value)}><option value="cycle">Current salary cycle</option><option value="month">This calendar month</option><option value="custom">Custom dates</option></select>}<button className="button primary" onClick={()=>setDialog({type:section==='accounts'||section==='cash'?'account':section==='budgets'?'budget':section==='recurring'?'recurring':section==='goals'?'goal':'transaction'})}><Plus size={17}/>{section==='accounts'||section==='cash'?'Add account':section==='budgets'?'Create budget':section==='recurring'?'Add bill':section==='goals'?'Create goal':'Add transaction'}</button></div></div>
      {range==='custom'&&['overview','insights'].includes(section)&&<div className="date-filter"><label>From<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>To<input type="date" value={end} min={start} onChange={e=>setEnd(e.target.value)}/></label></div>}
      {dashboard.isPending?<Loading/>:dashboard.error?<ErrorState message={dashboard.error.message} retry={()=>void dashboard.refetch()}/>:data&&<>
        {section==='overview'&&<Overview data={data} recent={recent.data?.items||[]} recentLoading={recent.isPending} recentError={recent.error?.message} retryRecent={()=>void recent.refetch()} categories={categories.data||[]} add={()=>setDialog({type:'transaction'})} createAccount={()=>setDialog({type:'account'})}/>}
        {section==='transactions'&&<Transactions accounts={data.accounts} categories={categories.data||[]} open={setDialog}/>}
        {(section==='accounts'||section==='cash')&&<Accounts accounts={data.accounts} cash={section==='cash'} open={setDialog} refresh={()=>void cache.invalidateQueries()}/>}
        {section==='budgets'&&<Budgets create={()=>setDialog({type:'budget'})}/>}
        {section==='insights'&&<Insights data={data}/>}
        {section==='recurring'&&<Bills open={setDialog} notify={setNotice}/>}
        {section==='goals'&&<Goals open={setDialog}/>}
        {section==='assistant'&&<Assistant/>}
        {section==='import'&&<Import accounts={data.accounts} notify={setNotice}/>}
        {section==='settings'&&user.data&&<Preferences user={user.data} notify={setNotice} logout={()=>{cache.clear();router.replace('/login');}}/>}
      </>}
      <footer className="page-footer"><span><span className="live-dot"/> A little clarity goes a long way.</span><span>Made for your everyday, and your someday.</span></footer></motion.div></main>
    </div>{notice&&<div className="toast" role="status"><Info size={17}/>{notice}<button className="icon-button" onClick={()=>setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}{dialog&&data&&<EntryDialog dialog={dialog} accounts={data.accounts} categories={categories.data||[]} dashboard={data} close={()=>setDialog(null)} done={done}/>}
  </div>;
}

const sectionDescriptions:Record<string,string>={transactions:'The everyday details behind your bigger picture.',accounts:'Every account, one connected picture.',cash:'Getting cash is a transfer. Spending it is an expense.',budgets:'Give your money a little direction.',insights:'Understand the patterns. Make your next move.',recurring:'A little planning. Fewer surprises.',goals:'Turn “one day” into a plan.',assistant:'Ask a question. Find a little clarity.',import:'Bring your transaction history into the picture.',settings:'Make this space work for you.'};

function Overview({data,recent,recentLoading,recentError,retryRecent,categories,add,createAccount}:{data:Dashboard;recent:Transaction[];recentLoading:boolean;recentError?:string;retryRecent:()=>void;categories:Category[];add:()=>void;createAccount:()=>void}) {
  return <><div className="overview-top"><section className="balance-panel panel"><div className="panel-overline"><span><Wallet size={16}/>AVAILABLE ACCOUNT BALANCE</span><span className="pill subtle">INR <span className="live-dot"/></span></div><div className="balance-amount">{money(data.available)}<span>INR</span></div><p className="balance-caption">Across your bank, cash and other accounts <span>·</span> Card debt {money(data.credit_debt)}</p><div className="balance-divider"/><div className="balance-stats"><div><span className="stat-icon income"><ArrowDownLeft size={18}/></span><div><span>Money in</span><strong>{money(data.income)}</strong></div></div><div><span className="stat-icon expense"><ArrowUpRight size={18}/></span><div><span>Money out, net of refunds</span><strong>{money(data.expenses)}</strong></div></div><div><span className="stat-icon saved"><TrendingUp size={18}/></span><div><span>Net savings</span><strong>{money(data.savings)}</strong></div></div></div></section><section className="safe-panel"><div className="safe-top"><span><Sparkles size={17}/> A LITTLE PEACE OF MIND</span><span className="safe-icon"><ArrowUpRight size={20}/></span></div><h2>{data.safe_to_spend>0?"You have room to spend.":"A moment to plan ahead."}</h2><div className="safe-amount">{money(data.safe_to_spend)}</div><p>Estimated until {dateLabel(data.cycle_end)}.<br/>After your reserves and budget limits.</p><div className="safe-bottom"><span><strong>{money(data.daily_safe)}</strong> / day</span><Link href="/insights">See the breakdown <ArrowRight size={15}/></Link></div></section></div>
    {!data.accounts.length&&<div className="onboarding-strip"><div><strong>Start with what you have.</strong><p>Add a bank account or cash wallet. Your picture builds from there.</p></div><button className="button secondary" onClick={createAccount}><Plus size={16}/>Add your first account</button></div>}
    <div className="content-grid"><section className="panel spending-panel"><div className="section-head"><div><h2>Your spending, in perspective</h2><p>{dateLabel(data.start_date)} – {dateLabel(data.end_date)}</p></div><Link className="text-link" href="/insights">Explore <ArrowUpRight size={15}/></Link></div><div className="spending-total">{money(data.expenses)}<span><span className="legend-dot"/> Net expenses</span></div><Trend points={data.trend}/></section><section className="panel category-panel"><div className="section-head"><div><h2>Where it went</h2><p>A little context for every rupee.</p></div><PieChart size={18} className="muted"/></div>{data.categories.length?<><div className="category-donut"><svg viewBox="0 0 120 120" role="img" aria-label="Spending by category"><circle cx="60" cy="60" r="45" fill="none" stroke="var(--border)" strokeWidth="13"/>{data.categories.reduce<{offset:number;nodes:React.ReactNode[]}>((acc,c)=>{const percent=c.amount/data.categories.reduce((s,x)=>s+x.amount,0);acc.nodes.push(<circle key={c.id||'none'} cx="60" cy="60" r="45" fill="none" stroke={c.color} strokeWidth="13" strokeDasharray={`${percent*282.74} ${282.74}`} strokeDashoffset={-acc.offset*282.74} transform="rotate(-90 60 60)"/>);acc.offset+=percent;return acc;},{offset:0,nodes:[]}).nodes}</svg><div><span>Total spent</span><strong>{money(data.categories.reduce((s,x)=>s+x.amount,0))}</strong></div></div><div className="category-list">{data.categories.slice(0,4).map(c=><div key={c.id||'none'}><span><i style={{background:c.color}}/>{c.name}</span><strong>{money(c.amount)}</strong></div>)}</div></>:<Empty title="Your spending story starts here" description="Add an expense to see your category breakdown." action="Add an expense" onAction={add}/>}</section></div>
    <div className="content-grid lower-grid"><section className="panel transactions-panel"><div className="section-head"><div><h2>The latest in your ledger</h2><p>Small moments. A bigger picture.</p></div><Link className="text-link" href="/transactions">View all <ArrowRight size={15}/></Link></div>{recentError?<ErrorState message={recentError} retry={retryRecent}/>:recentLoading?<p className="muted">Loading your latest transactions...</p>:recent.length?<TransactionTable rows={recent} accounts={data.accounts} categories={categories}/>:<Empty title="A clean slate" description="Your income, purchases and transfers will find a home here." action="Record your first transaction" onAction={add}/>}</section><div className="right-stack"><section className="panel"><div className="section-head"><h2>Your next commitments</h2><Link href="/recurring" className="icon-button" aria-label="View bills"><ArrowUpRight size={18}/></Link></div>{data.upcoming.length?data.upcoming.slice(0,3).map(b=><div className="bill-mini" key={b.id}><span className="bill-calendar"><span>{new Date(b.next_due+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</span><strong>{Number(b.next_due.slice(-2))}</strong></span><div><strong>{b.name}</strong><span>Scheduled · {b.frequency}</span></div><strong>{money(b.amount)}</strong></div>):<div className="quiet-empty">Nothing on the calendar yet.<Link href="/recurring">Plan a recurring bill <ArrowRight size={14}/></Link></div>}</section><section className="insight-note"><span className="insight-icon"><Sparkles size={19}/></span><span className="eyebrow">A MORROWMINT PERSPECTIVE</span><h3>{data.insights[0]?.title}</h3><p>{data.insights[0]?.detail}</p><Link href="/assistant">Let’s talk about your money <ArrowRight size={15}/></Link></section></div></div>
  </>;
}

function dateLabel(value:string) {return new Date(value+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}
function TransactionTable({rows,accounts,categories,open}:{rows:Transaction[];accounts:Account[];categories:Category[];open?:(d:Dialog)=>void}) {
  return <div className="table-scroll"><table><thead><tr><th>Transaction</th><th>Account / category</th><th>Date</th><th className="align-right">Amount</th>{open&&<th><span className="sr-only">Actions</span></th>}</tr></thead><tbody>{rows.map(t=><tr key={t.id}><td><div className="transaction-cell"><span className={`transaction-icon ${t.kind}`}>{t.kind==='transfer'?<ArrowLeftRight size={17}/>:t.kind==='income'||t.kind==='refund'?<ArrowDownLeft size={17}/>:<ArrowUpRight size={17}/>}</span><div><strong>{t.description}</strong><span>{t.kind==='transfer'?'Transfer · '+(accounts.find(a=>a.id===t.destination_id)?.name||'Account'):t.kind==='refund'?'Refund against original expense':t.source==='manual'?'Manual entry':t.source}{t.notes&&` · ${t.notes}`}</span></div></div></td><td><div className="table-account">{accounts.find(a=>a.id===t.account_id)?.name}<span>{categories.find(c=>c.id===t.category_id)?.name||'Uncategorized'}</span></div></td><td className="muted nowrap">{new Date(t.occurred_at).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'})}</td><td className={`align-right amount-cell ${['income','refund'].includes(t.kind)?'positive':''}`}>{t.kind==='transfer'?'':t.kind==='income'||t.kind==='refund'?'+':'−'}{money(t.amount)}</td>{open&&<td><details className="row-menu"><summary aria-label={`Actions for ${t.description}`}><MoreHorizontal size={17}/></summary><div>{t.kind!=='refund'&&<button onClick={()=>open({type:'edit',transaction:t})}><Pencil size={14}/>Correct entry</button>}{t.kind==='expense'&&<button onClick={()=>open({type:'refund',transaction:t})}><Undo2 size={14}/>Record refund</button>}<button onClick={()=>open({type:'reverse',transaction:t})}><Trash2 size={14}/>Reverse entry</button></div></details></td>}</tr>)}</tbody></table></div>;
}

function Transactions({accounts,categories,open}:{accounts:Account[];categories:Category[];open:(d:Dialog)=>void}) {
  const [search,setSearch]=useState(''),[kind,setKind]=useState(''),[account,setAccount]=useState(''),[category,setCategory]=useState(''),[page,setPage]=useState(1);
  const [debounced,setDebounced]=useState('');
  useEffect(()=>{const id=setTimeout(()=>{setDebounced(search);setPage(1);},300);return()=>clearTimeout(id);},[search]);
  const query=new URLSearchParams({page:String(page),search:debounced,...(kind?{kind}:{}),...(account?{account_id:account}:{}),...(category?{category_id:category}:{})});
  const results=useQuery({queryKey:['transactions',query.toString()],queryFn:()=>api<Page<Transaction>>('transactions?'+query)});
  return <section className="panel"><div className="section-head"><h2>Your transactions</h2><button className="text-link" onClick={()=>open({type:"category"})}><Plus size={14}/>Create category</button></div><div className="filter-bar"><div className="search-field"><Search size={17}/><input aria-label="Search transactions" placeholder="Find a transaction…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Filter type" value={kind} onChange={e=>{setKind(e.target.value);setPage(1);}}><option value="">All types</option>{['expense','income','transfer','refund'].map(t=><option key={t}>{t}</option>)}</select><select aria-label="Filter account" value={account} onChange={e=>{setAccount(e.target.value);setPage(1);}}><option value="">All accounts</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><select aria-label="Filter category" value={category} onChange={e=>{setCategory(e.target.value);setPage(1);}}><option value="">All categories</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div>{results.isPending?<Loading/>:results.error?<ErrorState message={results.error.message} retry={()=>void results.refetch()}/>:results.data?.items.length?<><TransactionTable rows={results.data.items} accounts={accounts} categories={categories} open={open}/><div className="pagination"><span>{results.data.total} transactions</span><div><button className="icon-button" aria-label="Previous page" disabled={page===1} onClick={()=>setPage(page-1)}><ChevronLeft size={18}/></button><span>Page {page}</span><button className="icon-button" aria-label="Next page" disabled={page*20>=results.data.total} onClick={()=>setPage(page+1)}><ChevronRight size={18}/></button></div></div></>:<Empty title="Nothing here just yet" description="Try another filter, or record a new transaction." action="Add transaction" onAction={()=>open({type:'transaction'})}/>}</section>;
}

function Accounts({accounts,cash,open,refresh}:{accounts:Account[];cash:boolean;open:(d:Dialog)=>void;refresh:()=>void}) {
  const [error,setError]=useState('');
  const rows=accounts.filter(a=>!cash||a.type==='cash');
  const archive=async(account:Account)=>{try{await api(`accounts/${account.id}`,{method:'PATCH',body:JSON.stringify({name:account.name,archived:!account.archived})});refresh();}catch(e){setError((e as Error).message);}};
  return <>{cash&&<div className="info-banner"><ArrowLeftRight size={21}/><div><strong>From bank to pocket. Still your money.</strong><p>Record ATM withdrawals and bank deposits as transfers. Only cash purchases count as spending.</p></div><button className="button secondary small" onClick={()=>open({type:'transfer'})}>Move money <ArrowRight size={15}/></button></div>}{error&&<div className="error-box" role="alert">{error}</div>}<div className="card-grid">{rows.map(a=><section key={a.id} className={`panel account-card ${a.archived?'archived':''}`}><div className="account-card-top"><span className={`account-type-icon ${a.type}`}>{a.type==='credit'?<CreditCard/>:a.type==='cash'?<Banknote/>:<Building2/>}</span><span className="pill subtle">{a.archived?'Archived':a.type==='credit'?'Credit card':a.type+' account'}</span></div><h2>{a.name}</h2><span className="muted">{a.type==='credit'?'Signed balance · negative means debt':'Calculated ledger balance'}</span><div className="account-amount">{money(a.balance)}</div><div className="account-card-bottom"><span>INR</span><button className="text-link" onClick={()=>void archive(a)}>{a.archived?'Restore account':'Archive account'}<ArrowUpRight size={14}/></button></div></section>)}<button className="add-card" onClick={()=>open({type:'account'})}><span className="empty-symbol"><Plus size={23}/></span><strong>{cash?'Create a cash wallet':'Add another account'}</strong><span>Bring your picture together.</span></button></div><div className="info-caption"><Info size={15}/> Opening balances reflect funds before your first recorded transaction. Corrections use ledger entries, so your history stays intact.</div></>;
}

function Budgets({create}:{create:()=>void}) {
  const query=useQuery({queryKey:['budgets'],queryFn:()=>api<Budget[]>('budgets')});
  if(query.isPending)return <Loading/>;if(query.error)return <ErrorState message={query.error.message} retry={()=>void query.refetch()}/>;
  return <><div className="info-banner"><PieChart size={23}/><div><strong>A plan for your kind of month.</strong><p>Set an overall limit or focus on a category. Choose weekly, monthly, salary-cycle or custom dates.</p></div></div>{query.data?.length?<div className="card-grid">{query.data.map(b=><section key={b.id} className="panel budget-card"><div className="section-head"><span className="account-type-icon"><PieChart/></span><span className={`pill ${b.utilization_bps>=10000?'warning':''}`}>{Math.round(b.utilization_bps/100)}% used</span></div><h2>{b.name}</h2><p>{dateLabel(b.start_date)} – {dateLabel(b.end_date)}</p><div className="budget-amount">{money(b.spent)}<span> / {money(b.amount)}</span></div><Progress value={b.utilization_bps} color={b.utilization_bps>=10000?'var(--red)':undefined}/><div className="budget-meta"><span>{b.remaining<0?'Over budget':'Remaining'}</span><strong>{money(Math.abs(b.remaining))}</strong></div><div className="budget-forecast">{b.preliminary?'Preliminary projection':'Pace projection'}: {money(b.projected)}<small>Current daily pace carried through this period.</small></div></section>)}</div>:<section className="panel"><Empty title="Give your money a direction" description="Your budget works with actual expenses and refunds. Transfers never use it up." action="Create your first budget" onAction={create}/></section>}</>;
}

function Insights({data}:{data:Dashboard}) {return <><div className="stats-grid"><div className="panel metric"><span>Cash spending, net of refunds</span><strong>{money(data.cash_expenses)}</strong><small>For the selected period</small></div><div className="panel metric"><span>Net savings rate</span><strong>{data.savings_rate_bps===null?'—':`${Math.round(data.savings_rate_bps/100)}%`}</strong><small>{data.savings_rate_bps===null?'Add income to calculate a rate':'Income less net expenses, divided by income'}</small></div><div className="panel metric"><span>Credit card debt</span><strong>{money(data.credit_debt)}</strong><small>Liabilities kept separate from available funds</small></div></div><div className="content-grid"><section className="panel"><div className="section-head"><div><h2>Your safe-to-spend estimate</h2><p>Current salary cycle · {dateLabel(data.cycle_start)} – {dateLabel(data.cycle_end)}</p></div><Sparkles size={20}/></div><div className="large-number">{money(data.safe_to_spend)}</div><dl className="breakdown"><div><dt>Available account funds</dt><dd>{money(data.available)}</dd></div><div><dt>Card debt reserved</dt><dd>− {money(data.credit_debt)}</dd></div><div><dt>Minimum balance reserve</dt><dd>− {money(data.minimum_balance)}</dd></div><div><dt>Essential unpaid bills</dt><dd>− {money(data.reserved_bills)}</dd></div><div><dt>Goal allocations</dt><dd>− {money(data.reserved_goals)}</dd></div><div><dt>Daily estimate · {data.days_remaining} days left</dt><dd>{money(data.daily_safe)}</dd></div></dl><p className="info-caption">{data.assumptions}</p></section><section className="panel"><div className="section-head"><h2>Worth a moment</h2><TrendingUp size={20}/></div>{data.insights.map((i,index)=><div className="insight-row" key={index}><span className="little-spark"><Sparkles size={17}/></span><div><h3>{i.title}</h3><p>{i.detail}</p></div></div>)}<div className="info-caption">Insights use recorded activity. Forecasts reflect a baseline pace and may change as you add history.</div></section></div></>;}

function Bills({open,notify}:{open:(d:Dialog)=>void;notify:(s:string)=>void}) {
  const cache=useQueryClient(),[busy,setBusy]=useState('');
  const query=useQuery({queryKey:['recurring'],queryFn:()=>api<Bill[]>('recurring')});
  const confirm=async(b:Bill)=>{setBusy(b.id);try{await api(`recurring/${b.id}/confirm?due_date=${b.next_due}`,{method:'POST'});void cache.invalidateQueries();notify('Payment recorded. The next reminder is scheduled.');}catch(e){notify((e as Error).message);}finally{setBusy('');}};
  if(query.isPending)return <Loading/>;if(query.error)return <ErrorState message={query.error.message} retry={()=>void query.refetch()}/>;
  return <section className="panel"><div className="section-head"><div><h2>On your calendar</h2><p>Reminders are plans. Confirm a payment only after it happens.</p></div><CalendarDays size={20}/></div>{query.data?.length?query.data.map(b=><div key={b.id} className="bill-row"><div className="bill-mini"><span className="bill-calendar"><span>{new Date(b.next_due+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</span><strong>{Number(b.next_due.slice(-2))}</strong></span><div><strong>{b.name}</strong><span>{b.frequency} · {b.essential?'Essential reserve':'Optional'} · {b.next_due<localDate()?'Overdue':'Scheduled'}</span></div></div><strong>{money(b.amount)}</strong><button className="button secondary small" disabled={busy===b.id||b.next_due>localDate()} onClick={()=>void confirm(b)}><Check size={15}/>{busy===b.id?'Recording…':'Confirm paid'}</button></div>):<Empty title="No surprises on the horizon" description="Add rent, subscriptions, and bills so you can plan ahead." action="Add your first bill" onAction={()=>open({type:'recurring'})}/>}</section>;
}

function Goals({open}:{open:(d:Dialog)=>void}) {
  const query=useQuery({queryKey:['goals'],queryFn:()=>api<Goal[]>('goals')});
  if(query.isPending)return <Loading/>;if(query.error)return <ErrorState message={query.error.message} retry={()=>void query.refetch()}/>;
  return <><div className="info-banner"><Target size={24}/><div><strong>Your someday deserves a plan.</strong><p>Contributions allocate existing funds to a goal and reserve them from safe-to-spend. They do not transfer money between accounts.</p></div></div>{query.data?.length?<div className="card-grid">{query.data.map(g=><section className="panel goal-card" key={g.id}><div className="section-head"><span className="account-type-icon"><Target/></span><span className="pill subtle">By {dateLabel(g.target_date)} {g.target_date.slice(0,4)}</span></div><h2>{g.name}</h2><div className="budget-amount">{money(g.saved)}<span> of {money(g.target)}</span></div><Progress value={g.progress_bps}/><div className="budget-meta"><span>{Math.round(g.progress_bps/100)}% of the way</span><strong>{money(Math.max(0,g.target-g.saved))} to go</strong></div><p className="goal-estimate">Aim for {money(g.monthly_required)} / month.<small>Estimate using 30-day months; no investment returns assumed.</small></p><button className="button secondary small" onClick={()=>open({type:'contribution',goal:g})}><Plus size={15}/>Allocate savings</button></section>)}</div>:<section className="panel"><Empty title="What are you making room for?" description="An emergency fund, a trip, a fresh start. Give your goal a name." action="Set your first goal" onAction={()=>open({type:'goal'})}/></section>}</>;
}

type Answer={answer:string;mode:string;tips:string[];period:string};
function Assistant() {
  const [question,setQuestion]=useState(''),[sharing,setSharing]=useState(false),[busy,setBusy]=useState(false),[messages,setMessages]=useState<{question:string;answer:Answer}[]>([]),[error,setError]=useState('');
  const ask=async(text:string)=>{if(!text.trim()||busy)return;setBusy(true);setError('');try{const answer=await api<Answer>('ai/ask',{method:'POST',body:JSON.stringify({question:text,share_with_ai:sharing})});setMessages(m=>[...m,{question:text,answer}]);setQuestion('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
  return <section className="panel assistant-panel"><div className="assistant-intro"><span className="copilot-orb"><Sparkles size={31}/></span><span className="eyebrow">YOUR MINT COPILOT</span><h2>Money questions.<br/><em>A little more clarity.</em></h2><p>English or Hinglish. Let’s make sense of your recorded finances.</p></div><div className="suggestions">{['How much have I spent this month?','Kya main aur spend kar sakta hoon?','What is my biggest spending category?','How can I reach my savings goals?'].map(q=><button key={q} onClick={()=>void ask(q)} disabled={busy}>{q}<ArrowUpRight size={16}/></button>)}</div><div className="conversation" aria-live="polite">{messages.map((m,i)=><div key={i}><div className="user-message">{m.question}</div><div className="assistant-message"><Sparkles size={20}/><div><span className="eyebrow">{m.answer.mode==='groq'?'AI-ASSISTED · VERIFIED FINANCIAL FACTS':'CALCULATED FROM YOUR RECORDS'}</span><p>{m.answer.answer}</p>{m.answer.tips.map(t=><p key={t} className="assistant-tip">{t}</p>)}<small>{m.answer.period}</small></div></div></div>)}{busy&&<p className="muted">Finding a little clarity…</p>}</div>{error&&<div className="error-box" role="alert">{error}</div>}<form className="question-form" onSubmit={e=>{e.preventDefault();void ask(question);}}><input aria-label="Your finance question" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={1000} placeholder="Ask about your money…"/><button className="button primary" aria-label="Send question" disabled={busy||question.trim().length<2}><Send size={18}/></button></form><label className="check-label"><input type="checkbox" checked={sharing} onChange={e=>setSharing(e.target.checked)}/> Use Groq to interpret this question and aggregate financial context. No transaction descriptions are shared.</label><p className="info-caption"><ShieldCheck size={15}/> The financial service calculates every amount. Optional AI selects the topic and guidance. Your core features work without AI.</p></section>;
}

function Import({accounts,notify}:{accounts:Account[];notify:(s:string)=>void}) {
  const cache=useQueryClient(),[account,setAccount]=useState(''),[csv,setCsv]=useState(''),[job,setJob]=useState<ImportJob|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const [mapping,setMapping]=useState({date:'date',amount:'amount',kind:'type',description:'description'});
  const read=async(file?:File)=>{if(!file)return;if(file.size>500000){setError('Choose a CSV file smaller than 500 KB.');return;}setCsv(await file.text());setJob(null);};
  const preview=async()=>{setBusy(true);setError('');try{setJob(await api<ImportJob>('imports/preview',{method:'POST',body:JSON.stringify({account_id:account,csv_text:csv,mapping})}));}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
  const commit=async()=>{setBusy(true);try{const r=await api<{imported:number}>(`imports/${job!.id}/commit`,{method:'POST'});setJob({...job!,committed:true});void cache.invalidateQueries();notify(`${r.imported} transactions imported. Your ledger is up to date.`);}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
  return <section className="panel import-panel"><div className="section-head"><div><h2>Bring your history along</h2><p>Upload, map, review, then confirm. Nothing is imported until you approve.</p></div><Upload size={23}/></div><div className="form-grid"><label>Import into account<select value={account} onChange={e=>{setAccount(e.target.value);setJob(null);}} required><option value="">Choose an account</option>{accounts.filter(a=>!a.archived).map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label>CSV file · up to 500 KB<input type="file" accept=".csv,text/csv" onChange={e=>void read(e.target.files?.[0])}/></label></div><div className="info-caption">Dates: ISO 8601 (YYYY-MM-DD). Amounts: positive INR values with up to two decimals. Types: income or expense. Transfers and refunds require manual review in the ledger.</div><div className="form-grid mapping-grid">{Object.entries(mapping).map(([key,value])=><label key={key}>{key} column<input value={value} onChange={e=>{setMapping({...mapping,[key]:e.target.value});setJob(null);}}/></label>)}</div><label>CSV contents<textarea rows={6} value={csv} onChange={e=>{setCsv(e.target.value);setJob(null);}} placeholder={'date,amount,type,description\n2026-10-01,125.50,expense,Lunch'}/></label>{error&&<div className="error-box" role="alert">{error}</div>}<button className="button secondary" disabled={busy||!account||!csv} onClick={()=>void preview()}>{busy?'Working…':'Preview & validate'}<ArrowRight size={16}/></button>{job&&<div className="import-preview"><div className="section-head"><div><h2>Review {job.records.length} rows</h2><p>{job.records.filter(r=>!r.error).length} eligible · invalid and possible duplicate rows are skipped</p></div><span className="pill">{job.committed?'Imported':'Awaiting your review'}</span></div><div className="table-scroll"><table><thead><tr><th>Row</th><th>Description</th><th>Amount</th><th>Status</th></tr></thead><tbody>{job.records.map(r=><tr key={r.id}><td>{r.row_number}</td><td>{r.data.description||'—'}</td><td>{r.data.amount?money(r.data.amount):'—'}</td><td className={r.error?'field-error':'positive'}>{r.error||'Ready to import'}</td></tr>)}</tbody></table></div><button className="button primary" disabled={busy||job.committed||!job.records.some(r=>!r.error)} onClick={()=>void commit()}><Check size={16}/>Confirm import</button></div>}</section>;
}

function Preferences({user,notify,logout}:{user:User;notify:(s:string)=>void;logout:()=>void}) {
  const cache=useQueryClient(),[busy,setBusy]=useState(false),[error,setError]=useState(''),[deleting,setDeleting]=useState(false);
  const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');try{const f=new FormData(e.currentTarget);await api('settings',{method:'PATCH',body:JSON.stringify({name:f.get('name'),salary_day:Number(f.get('salary_day')),minimum_balance:toPaise(String(f.get('minimum_balance')))})});void cache.invalidateQueries();notify('Your preferences are saved.');}catch(err){setError((err as Error).message);}finally{setBusy(false);}};
  const exportData=async()=>{try{const data=await api('settings/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`paisasense-export-${localDate()}.json`;a.click();URL.revokeObjectURL(url);}catch(e){notify((e as Error).message);}};
  return <div className="settings-grid"><section className="panel"><div className="section-head"><div><h2>A rhythm that fits your life</h2><p>Your preferences shape your current salary cycle and estimates.</p></div><Settings size={19}/></div><form onSubmit={save}><label>Your name<input name="name" required maxLength={80} defaultValue={user.name}/></label><label>Email<input value={user.email} disabled/></label><div className="form-grid"><label>Salary / budget cycle starts on<select name="salary_day" defaultValue={user.salary_day}>{Array.from({length:31},(_,i)=><option key={i} value={i+1}>Day {i+1}</option>)}</select></label><label>Minimum balance to reserve · INR<input name="minimum_balance" inputMode="decimal" required defaultValue={(user.minimum_balance/100).toFixed(2)}/></label></div><p className="info-caption">A start day beyond a month’s last day uses that last day. Currency: INR. Financial dates use Asia/Kolkata.</p>{error&&<div className="error-box" role="alert">{error}</div>}<button disabled={busy} className="button primary">{busy?'Saving…':'Save preferences'}<Check size={16}/></button></form></section><div className="right-stack"><section className="panel"><div className="section-head"><h2>Your data belongs to you</h2><ShieldCheck size={19}/></div><p className="muted">Download your profile, accounts, ledger, budgets, goals and audit history as JSON.</p><button className="button secondary" onClick={()=>void exportData()}><Download size={16}/>Export my data</button></section><section className="panel danger-zone"><h2>Close your account</h2><p>This permanently removes your account and its financial records from the application database.</p><button className="text-link danger" onClick={()=>setDeleting(true)}>Delete my account <Trash2 size={15}/></button></section></div>{deleting&&<Modal title="Delete your account?" close={()=>setDeleting(false)}><p className="muted">This cannot be undone. Export your data first. Backups may retain data until their documented expiry.</p><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('settings/account',{method:'DELETE',body:JSON.stringify({email:user.email,password:f.get('password')})});logout();}catch(err){setError((err as Error).message);}}}><label>Confirm your password<input name="password" type="password" required autoComplete="current-password"/></label>{error&&<div className="error-box" role="alert">{error}</div>}<button className="button danger-button">Permanently delete account</button></form></Modal>}</div>;
}

function EntryDialog({dialog,accounts,categories,dashboard,close,done}:DialogProps) {
  const item=dialog.transaction,[kind,setKind]=useState(dialog.type==='transfer'?'transfer':item?.kind||'expense'),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const [voice,setVoice]=useState(''),[listening,setListening]=useState(false);
  const key=useRef(crypto.randomUUID()), form=useRef<HTMLFormElement>(null);
  const type=dialog.type, transaction=['transaction','transfer','edit','refund'].includes(type),active=accounts.filter(a=>!a.archived);
  const title=type==='category'?'Create a spending category':type==='account'?'Add a financial account':type==='budget'?'Make a spending plan':type==='recurring'?'Plan a recurring bill':type==='goal'?'Make room for a goal':type==='contribution'?`Save for ${dialog.goal?.name}`:type==='reverse'?'Reverse this transaction?':type==='refund'?'Record a refund':type==='edit'?'Correct this transaction':'A new entry in your story';
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');try{
    const f=new FormData(e.currentTarget), text=(name:string)=>String(f.get(name)||''), amount=(name='amount')=>toPaise(text(name));
    let endpoint='',method='POST',payload:unknown;
    if(transaction){endpoint=type==='edit'?`transactions/${item!.id}`:'transactions';method=type==='edit'?'PUT':'POST';payload={account_id:type==='refund'?item!.account_id:text('account_id'),kind:type==='refund'?'refund':kind,amount:amount(),description:text('description'),occurred_at:`${text('date')}T12:00:00+05:30`,notes:text('notes'),category_id:text('category_id')||null,destination_id:kind==='transfer'&&type!=='refund'?text('destination_id'):null,original_id:type==='refund'?item!.id:null,source:voice?'voice':'manual'};}
    else if(type==='account'){endpoint='accounts';payload={name:text('name'),type:text('type'),opening_balance:amount('opening_balance')};}
    else if(type==='budget'){endpoint='budgets';payload={name:text('name'),amount:amount(),category_id:text('category_id')||null,start_date:text('start_date'),end_date:text('end_date')};}
    else if(type==='recurring'){endpoint='recurring';payload={name:text('name'),amount:amount(),account_id:text('account_id'),next_due:text('next_due'),frequency:text('frequency'),essential:f.get('essential')==='on'};}
    else if(type==='goal'){endpoint='goals';payload={name:text('name'),target:amount('target'),target_date:text('target_date')};}
    else if(type==='category'){endpoint='categories';payload={name:text('name'),color:text('color')};}
    else if(type==='contribution'){endpoint=`goals/${dialog.goal!.id}/contributions`;payload={amount:amount()};}
    else if(type==='reverse'){endpoint=`transactions/${item!.id}`;method='DELETE';}
    else return;
    await api(endpoint,{method,body:payload?JSON.stringify(payload):undefined,headers:transaction&&type!=='edit'?{'Idempotency-Key':key.current}:{}});done();
  }catch(err){setError((err as Error).message);}finally{setBusy(false);}};
  const speech=()=>{
    type Recognition={lang:string;interimResults:boolean;onresult:((e:{results:{transcript:string}[][]})=>void)|null;onerror:((e:unknown)=>void)|null;onend:(()=>void)|null;start:()=>void};
    const Speech=(window as unknown as {SpeechRecognition?:new()=>Recognition;webkitSpeechRecognition?:new()=>Recognition}).SpeechRecognition||(window as unknown as {webkitSpeechRecognition?:new()=>Recognition}).webkitSpeechRecognition;
    if(!Speech){setError('Speech recognition is unavailable in this browser. Type a sentence below, then review the fields.');return;}
    const recognition=new Speech();recognition.lang='hi-IN';recognition.interimResults=false;recognition.onresult=e=>{setVoice(e.results[0][0].transcript);setListening(false);};recognition.onerror=()=>{setListening(false);setError('Could not capture speech. You can type the sentence below.');};recognition.onend=()=>setListening(false);setListening(true);recognition.start();
  };
  const parseVoice=()=>{const match=voice.match(/(?:₹|rs\.?\s*)?(\d+(?:\.\d{1,2})?)/i);if(!match){setError('Could not find an amount. Enter it manually and review the details.');return;}const element=form.current;const set=(name:string,value:string)=>{const input=element?.elements.namedItem(name) as HTMLInputElement|null;if(input)input.value=value;};set('amount',match[1]);set('description',voice.slice(0,200));if(/\bkal\b|yesterday/i.test(voice)){const date=new Date(localDate()+'T12:00:00+05:30');date.setUTCDate(date.getUTCDate()-1);set('date',new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(date));}setError('');};
  const accountField=<label>From account<select name="account_id" defaultValue={item?.account_id||''} required><option value="">Choose an account</option>{active.map(a=><option key={a.id} value={a.id}>{a.name} · {money(a.balance)}</option>)}</select></label>;
  const categoryField=<label>Category<select name="category_id" defaultValue={item?.category_id||''}><option value="">Uncategorized</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>;
  return <Modal title={title} close={close}><form onSubmit={submit} ref={form}>
    {transaction&&<>{type!=='refund'&&<div className="segmented">{['expense','income','transfer'].map(k=><button type="button" key={k} className={kind===k?'selected':''} onClick={()=>setKind(k)}>{k}</button>)}</div>}{type==='transaction'&&<details className="voice-entry"><summary><Mic size={15}/> Speak or type a quick entry <span className="pill subtle">REVIEW FIRST</span></summary><p>Some browsers send speech to their recognition provider. Use text if you prefer.</p><div className="voice-input"><input value={voice} onChange={e=>setVoice(e.target.value)} placeholder="Kal maine 250 ka petrol bharwaya"/><button type="button" className="icon-button" onClick={speech} disabled={listening} aria-label="Start speech recognition"><Mic size={18}/></button></div><button type="button" className="text-link" onClick={parseVoice}>Fill fields for review <ArrowRight size={14}/></button></details>}<div className="form-grid"><label>Amount · INR<input name="amount" required inputMode="decimal" placeholder="0.00" defaultValue={type==='edit'?((item?.amount||0)/100).toFixed(2):''}/></label><label>Date · Asia/Kolkata<input name="date" type="date" required defaultValue={type==='edit'?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(item!.occurred_at)):localDate()}/></label></div><label>Description<input name="description" required maxLength={200} placeholder="What was it for?" defaultValue={type==='refund'?`Refund · ${item?.description}`:item?.description||''}/></label>{type==='refund'?<div className="info-banner">Refund returns to the original account. The backend checks the remaining refundable amount.</div>:<div className="form-grid">{accountField}{kind==='transfer'?<label>To account<select name="destination_id" required defaultValue={item?.destination_id||''}><option value="">Choose destination</option>{active.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label>:categoryField}</div>}<label>Notes <span className="muted">· optional</span><textarea name="notes" rows={2} maxLength={1000} defaultValue={item?.notes||''}/></label>{kind==='transfer'&&type!=='refund'&&<p className="info-caption">ATM withdrawal? Choose bank → cash. Card repayment? Choose bank → credit card. Transfers do not count as expenses.</p>}</>}
    {type==='account'&&<><label>Account name<input name="name" placeholder="My salary account" required maxLength={80}/></label><label>Account type<select name="type"><option value="bank">Bank account</option><option value="cash">Cash wallet</option><option value="credit">Credit card</option><option value="other">Other funds</option></select></label><label>Opening signed balance · INR<input name="opening_balance" required inputMode="decimal" defaultValue="0.00"/></label><p className="info-caption">For a credit card with ₹5,000 owed, enter −5000. Add only transactions after this balance snapshot to avoid double counting.</p></>}
    {type==='budget'&&<><label>Budget name<input name="name" placeholder="A more intentional month" required maxLength={80}/></label><div className="form-grid"><label>Spending limit · INR<input name="amount" inputMode="decimal" required placeholder="0.00"/></label>{categoryField}</div><div className="form-grid"><label>Start date<input name="start_date" type="date" required defaultValue={dashboard.cycle_start}/></label><label>End date<input name="end_date" type="date" required defaultValue={dashboard.cycle_end}/></label></div><p className="info-caption">Dates are inclusive in India time. Leave category blank for an overall limit. Budgets are explicit periods; create the next period when needed.</p></>}
    {type==='recurring'&&<><label>Bill name<input name="name" required maxLength={80} placeholder="Internet, rent, or something else"/></label><div className="form-grid"><label>Amount · INR<input name="amount" inputMode="decimal" required/></label><label>Next due date<input name="next_due" type="date" required defaultValue={localDate()}/></label></div><div className="form-grid">{accountField}<label>Repeats<select name="frequency"><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="yearly">Yearly</option></select></label></div><label className="check-label"><input name="essential" type="checkbox" defaultChecked/>Reserve this bill in safe-to-spend</label><p className="info-caption">For credit-card repayments, record a transfer manually. This reminder form creates expense payments only.</p></>}
    {type==='goal'&&<><label>What are you saving for?<input name="name" required maxLength={80} placeholder="My emergency fund"/></label><label>Target amount · INR<input name="target" inputMode="decimal" required/></label><label>Target date<input name="target_date" type="date" required min={localDate()}/></label></>}
    {type==='category'&&<><label>Category name<input name="name" required maxLength={60} placeholder="A category that fits your life"/></label><label>Category color<input name="color" type="color" defaultValue="#35D39A"/></label></>}
    {type==='contribution'&&<><p className="muted">Allocate existing savings to this goal. This reserves funds in your safe-to-spend estimate and does not create an income or transfer.</p><label>Amount to allocate · INR<input name="amount" inputMode="decimal" required/></label></>}
    {type==='reverse'&&<div className="info-banner">“{item?.description}” will stop affecting your balances and reports. The original record stays in your audit history. Associated refunds must be reversed first.</div>}
    {type==='edit'&&<p className="info-caption">A correction reverses the old record and creates its replacement together. Both remain in your audit history.</p>}{!active.length&&transaction&&<p className="field-error">Add an active account before recording transactions.</p>}{error&&<div className="error-box" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Cancel</button><button disabled={busy||(transaction&&!active.length)} className={`button ${type==='reverse'?'danger-button':'primary'}`}>{busy?'Saving…':type==='reverse'?'Confirm reversal':type==='refund'?'Confirm refund':transaction?'Confirm & save':'Save'}<Check size={16}/></button></div>
  </form></Modal>;
}
